import { describe, expect, it, vi } from 'vitest';
import { createSleepTimer, type SleepTimer } from './sleepTimer.js';

/**
 * Protected test-first contract. Continue with implementation; do not edit this file.
 * Minimal additive interface on the EXISTING SleepTimer: readonly `progress`,
 * a detached snapshot derived from its injected now()/existing arming:
 *   null | { kind: 'duration'; remainingMs: number }
 *        | { kind: 'end-of-track' }
 *        | { kind: 'stop-after-tracks'; remainingTracks: number }.
 * Reading progress MUST NOT tick, fire, re-arm or schedule anything. No new
 * constructor, formatter, module, timestamp or UI polling API is prescribed.
 * The optional local type lets baseline source compile: missing progress is an
 * assertion failure, never an import/compiler failure. Browser contract lives
 * in tests/player-sleep-status.spec.ts. IDs SLP-Uxx are stable handoff IDs.
 */
type Progress =
	| { readonly kind: 'duration'; readonly remainingMs: number }
	| { readonly kind: 'end-of-track' }
	| { readonly kind: 'stop-after-tracks'; readonly remainingTracks: number }
	| null;
type ProgressTimer = SleepTimer & { readonly progress?: Progress };

function harness() {
	const clock = { now: 1_000_000 };
	const onFire = vi.fn();
	const timer: ProgressTimer = createSleepTimer({ now: () => clock.now, onFire });
	return { clock, onFire, timer };
}

function progress(timer: ProgressTimer): Progress | undefined {
	expect(timer, 'Expose a read-only progress snapshot on the existing timer').toHaveProperty('progress');
	return timer.progress;
}

// Catches tick-count countdowns, progress reads that re-arm/fire, stale mode
// snapshots, mutations leaking into the authority, and rejected replacement resets.
describe('sleep progress from the single existing authority', () => {
	it('SLP-U01 reads elapsed wall time before any tick and clamps without firing', () => {
		const { clock, timer, onFire } = harness();
		timer.start({ kind: 'duration', ms: 90_000 });
		expect(progress(timer)).toEqual({ kind: 'duration', remainingMs: 90_000 });
		clock.now = 1_012_345;
		expect(progress(timer)).toEqual({ kind: 'duration', remainingMs: 77_655 });
		clock.now = 1_089_999;
		expect(progress(timer)).toEqual({ kind: 'duration', remainingMs: 1 });
		clock.now = 1_090_000;
		expect(progress(timer)).toEqual({ kind: 'duration', remainingMs: 0 });
		clock.now = 1_900_000; // background delay, not 810 assumed interval ticks
		expect(progress(timer)).toEqual({ kind: 'duration', remainingMs: 0 });
		expect(onFire).not.toHaveBeenCalled();
		expect(timer.mode).toEqual({ kind: 'duration', ms: 90_000 });
		expect(timer.tick()).toBe(true);
		expect(progress(timer)).toBeNull();
		expect(onFire).toHaveBeenCalledTimes(1);
	});

	it('SLP-U02 repeated display reads do not restart the deadline or count tracks', () => {
		const { clock, timer, onFire } = harness();
		timer.start({ kind: 'duration', ms: 1_000 });
		clock.now = 1_000_400;
		for (let i = 0; i < 20; i += 1) {
			expect(progress(timer)).toEqual({ kind: 'duration', remainingMs: 600 });
		}
		expect(timer.tracksElapsed).toBe(0);
		expect(onFire).not.toHaveBeenCalled();
		clock.now = 1_000_999;
		expect(timer.tick()).toBe(false);
		clock.now = 1_001_000;
		expect(timer.tick()).toBe(true);
		expect(timer.tick()).toBe(false);
		expect(timer.trackEnded()).toBe(false);
		expect(onFire).toHaveBeenCalledTimes(1);
	});

	it('SLP-U03 snapshots are detached from subsequent reads and cannot mutate arming', () => {
		const { clock, timer } = harness();
		timer.start({ kind: 'duration', ms: 5_000 });
		const first = progress(timer);
		clock.now = 1_001_000;
		expect(progress(timer)).toEqual({ kind: 'duration', remainingMs: 4_000 });
		expect(first).toEqual({ kind: 'duration', remainingMs: 5_000 });
		// Both frozen snapshots and writable detached copies satisfy read-only state.
		try { Object.assign(first!, { remainingMs: 900_000 }); } catch { /* frozen is fine */ }
		expect(progress(timer)).toEqual({ kind: 'duration', remainingMs: 4_000 });
		expect(timer.mode).toEqual({ kind: 'duration', ms: 5_000 });
	});

	it('SLP-U04 end-of-track is explicit, never a fictitious time/count countdown', () => {
		const { clock, timer, onFire } = harness();
		timer.start({ kind: 'end-of-track' });
		clock.now += 86_400_000;
		expect(progress(timer)).toEqual({ kind: 'end-of-track' });
		expect(timer.tick()).toBe(false);
		expect(onFire).not.toHaveBeenCalled();
		expect(timer.trackEnded()).toBe(true);
		expect(progress(timer)).toBeNull();
		expect(timer.trackEnded()).toBe(false);
		expect(onFire).toHaveBeenCalledTimes(1);
	});

	it('SLP-U05 after-N reports remaining natural completions, not original count', () => {
		const { clock, timer, onFire } = harness();
		timer.start({ kind: 'stop-after-tracks', count: 3 });
		expect(progress(timer)).toEqual({ kind: 'stop-after-tracks', remainingTracks: 3 });
		clock.now += 86_400_000;
		expect(timer.tick()).toBe(false);
		expect(timer.trackEnded()).toBe(false);
		expect(progress(timer)).toEqual({ kind: 'stop-after-tracks', remainingTracks: 2 });
		expect(timer.trackEnded()).toBe(false);
		expect(progress(timer)).toEqual({ kind: 'stop-after-tracks', remainingTracks: 1 });
		expect(onFire).not.toHaveBeenCalled();
		expect(timer.trackEnded()).toBe(true);
		expect(progress(timer)).toBeNull();
		expect(timer.tracksElapsed).toBe(3);
		expect(onFire).toHaveBeenCalledTimes(1);
	});

	it('SLP-U06 replacement resets progress; old deadline observations cannot expire it', () => {
		const { clock, timer, onFire } = harness();
		timer.start({ kind: 'duration', ms: 1_000 });
		clock.now += 500;
		timer.start({ kind: 'duration', ms: 3_000 });
		clock.now = 1_001_000;
		expect(timer.tick()).toBe(false); // an old refresh/expiry callback
		expect(progress(timer)).toEqual({ kind: 'duration', remainingMs: 2_500 });
		expect(timer.tick(1_001_000)).toBe(false);
		clock.now = 1_003_499;
		expect(progress(timer)).toEqual({ kind: 'duration', remainingMs: 1 });
		expect(timer.tick()).toBe(false);
		clock.now = 1_003_500;
		expect(timer.tick()).toBe(true);
		for (let i = 0; i < 5; i += 1) expect(timer.tick()).toBe(false);
		expect(progress(timer)).toBeNull();
		expect(onFire).toHaveBeenCalledTimes(1);
		timer.start({ kind: 'stop-after-tracks', count: 4 });
		timer.trackEnded();
		timer.start({ kind: 'stop-after-tracks', count: 2 });
		expect(progress(timer)).toEqual({ kind: 'stop-after-tracks', remainingTracks: 2 });
	});

	it('SLP-U07 cancel removes progress and all late ticks/ends remain inert', () => {
		const { clock, timer, onFire } = harness();
		expect(progress(timer)).toBeNull();
		for (const mode of [
			{ kind: 'duration', ms: 1_000 }, { kind: 'end-of-track' },
			{ kind: 'stop-after-tracks', count: 2 }
		] as const) {
			timer.start(mode);
			timer.cancel();
			clock.now += 100_000;
			expect(progress(timer)).toBeNull();
			expect(timer.tick()).toBe(false);
			expect(timer.trackEnded()).toBe(false);
		}
		expect(onFire).not.toHaveBeenCalled();
	});

	it('SLP-U08 invalid replacement leaves the original elapsed deadline intact', () => {
		const { clock, timer, onFire } = harness();
		timer.start({ kind: 'duration', ms: 60_000 });
		clock.now += 15_000;
		for (const ms of [0, -1, NaN, Infinity, -Infinity, 1e308 * 60_000]) {
			expect(() => timer.start({ kind: 'duration', ms })).toThrow(RangeError);
			expect(progress(timer)).toEqual({ kind: 'duration', remainingMs: 45_000 });
		}
		for (const count of [0, -1, 1.5, NaN, Infinity]) {
			expect(() => timer.start({ kind: 'stop-after-tracks', count })).toThrow(RangeError);
			expect(progress(timer)).toEqual({ kind: 'duration', remainingMs: 45_000 });
		}
		clock.now += 45_000;
		expect(timer.tick()).toBe(true);
		expect(onFire).toHaveBeenCalledTimes(1);
	});

	it('SLP-U09 fractional and large finite durations retain existing bounds', () => {
		const { clock, timer } = harness();
		timer.start({ kind: 'duration', ms: 0.5 * 60_000 });
		clock.now += 500;
		expect(progress(timer)).toEqual({ kind: 'duration', remainingMs: 29_500 });
		timer.start({ kind: 'duration', ms: 10_000 * 60_000 });
		clock.now += 1;
		expect(progress(timer)).toEqual({ kind: 'duration', remainingMs: 599_999_999 });
	});
});

// Independent controls still execute on baseline even when progress is absent.
describe('existing authority controls', () => {
	it('SLP-U10 tick alone owns the exact boundary and repeated expiry is idempotent', () => {
		const { clock, timer, onFire } = harness();
		timer.start({ kind: 'duration', ms: 30_000 });
		clock.now += 29_999;
		expect(timer.tick()).toBe(false);
		clock.now += 1;
		expect(timer.tick()).toBe(true);
		expect(timer.tick()).toBe(false);
		expect(timer.trackEnded()).toBe(false);
		expect(onFire).toHaveBeenCalledTimes(1);
	});

	it('SLP-U11 rejected overflow cannot replace a running timer', () => {
		const { timer, onFire } = harness();
		timer.start({ kind: 'end-of-track' });
		expect(() => timer.start({ kind: 'duration', ms: 1e308 * 60_000 })).toThrow(RangeError);
		expect(timer.mode).toEqual({ kind: 'end-of-track' });
		expect(timer.trackEnded()).toBe(true);
		expect(onFire).toHaveBeenCalledTimes(1);
	});
});
